@import '@taiga-ui/core/styles/taiga-ui-local';

.tooltip {
    height: 1.25rem;
    min-width: 6.25rem;
}

.wrapping-tooltip {
    width: fit-content;
    max-width: 11rem;
    background: var(--tui-background-base-alt);
    border-radius: 0.5rem;
    line-height: 1.5rem;
    padding: 0.375rem 1.875rem 0.375rem 0.5rem;
    resize: horizontal;
    overflow: auto;

    & [tuiTooltip] {
        position: absolute;
    }
}

:host {
    display: block;
    width: 25rem;
}

.primary {
    color: var(--tui-background-accent-1);
}

.input {
    display: inline-block;
    width: 18.75rem;
    margin: 0.75rem 0.75rem 0.75rem 0;
    vertical-align: middle;
}

:host {
    display: flex;
    flex-direction: column;
    gap: 3rem;
}

.description {
    font: var(--tui-font-text-l);
    margin-top: 0.5rem;
    max-width: 30rem;
}

@import '@taiga-ui/core/styles/taiga-ui-local';

form {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 1rem;
}

.content {
    display: flex;
    align-items: center;
}

.label {
    font: var(--tui-font-text-s);
    color: var(--tui-text-tertiary);
}

.text {
    font: var(--tui-font-text-s);
    margin-top: 0.25rem;
    color: var(--tui-text-secondary);
}

.inner {
    margin: 1rem 0;
    white-space: normal;

    &_flex {
        display: flex;
        justify-content: space-between;
        margin: 0;
        width: 15rem;
    }
}

